cards.solution:
const angka = document.querySelector("#angka");
const kurang = document.querySelector("#kurang");
const tambah = document.querySelector("#tambah");
let nilai = 0;
tambah.addEventListener("click", () => {
  nilai++;
  angka.textContent = nilai;
});
kurang.addEventListener("click", () => {
  if (nilai > 0) nilai--;
  angka.textContent = nilai;
});
tambah.click();
tambah.click();
kurang.click();
console.log(angka.textContent);
kurang.click();
kurang.click();
console.log(angka.textContent);
